#!/bin/sh
# Start the LMS. Creates .env (no secrets in it) on first run, and asks you to
# create the first admin account interactively if none exists yet.
set -e
cd "$(dirname "$0")"

if [ ! -f .env ]; then
  rand() { python3 -c "import secrets; print(secrets.token_urlsafe($1))"; }
  umask 077
  cat > .env <<EOF
# Generated by setup.sh. Contains no passwords or keys.
DJANGO_DEBUG=0
DJANGO_ALLOWED_HOSTS=localhost,127.0.0.1
# Add https://your.domain here when using a real domain.
DJANGO_CSRF_TRUSTED_ORIGINS=
# Admin page path (hard to guess).
ADMIN_URL=quan-tri-$(rand 9)/
# 1 = create demo courses/accounts (password demo1234). Never on a real server.
SEED_DEMO=0
# ":80" = plain HTTP on localhost. Real domain, e.g. lms.example.com = automatic HTTPS
# (then also set HTTPS=1, HTTP_PORT=80, HTTPS_PORT=443).
SITE_ADDRESS=:80
HTTPS=0
HTTP_PORT=8000
HTTPS_PORT=8443
EOF
  echo "Created .env"
fi

docker compose up -d --build

has_admin=$(docker compose exec -T web python manage.py shell -c \
  "from django.contrib.auth import get_user_model as g; print(int(g().objects.filter(is_superuser=True).exists()))" | tail -1)

if [ "$has_admin" != "1" ]; then
  echo
  echo "Chưa có tài khoản quản trị. Tạo ngay (mật khẩu chỉ lưu dạng hash trong database):"
  if [ -t 0 ]; then
    docker compose exec web python manage.py createsuperuser
  else
    echo "  docker compose exec web python manage.py createsuperuser"
  fi
fi

port=$(grep ^HTTP_PORT= .env | cut -d= -f2)
echo
echo "LMS:   http://localhost:$port"
echo "Admin: http://localhost:$port/$(grep ^ADMIN_URL= .env | cut -d= -f2)"
